    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder cannot be null");
    }
    if (i < 0 || i >= bb.remaining()) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }
    bb.position(i);
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b < 128) {
            sb.append((char) b);
        } else {
            // Handle multi-byte UTF-8 characters
            int numBytes = 0;
            if ((b & 0xE0) == 0xC0) {
                numBytes = 1;
            } else if ((b & 0xF0) == 0xE0) {
                numBytes = 2;
            } else if ((b & 0xF8) == 0xF0) {
                numBytes = 3;
            } else {
                // Invalid UTF-8 start byte
                throw new IllegalArgumentException("Invalid UTF-8 start byte");
            }
            if (bb.remaining() < numBytes) {
                throw new IllegalArgumentException("Not enough bytes for UTF-8 character");
            }
            int codePoint = b & ((1 << (7 - numBytes)) - 1);
            for (int j = 0; j < numBytes; j++) {
                b = bb.get() & 0xFF;
                if ((b & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
                }
                codePoint = (codePoint << 6) | (b & 0x3F);
            }
            sb.appendCodePoint(codePoint);
        }
    }
    return bb.position();
}

