private static String performVariableSubstitution(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int startIndex = 0;
    while (startIndex < value.length()) {
        int dollarIndex = value.indexOf('$', startIndex);
        if (dollarIndex == -1) {
            result.append(value.substring(startIndex));
            break;
        }
        result.append(value.substring(startIndex, dollarIndex));
        if (dollarIndex + 1 < value.length() && value.charAt(dollarIndex + 1) == '{') {
            int endIndex = value.indexOf('}', dollarIndex + 2);
            if (endIndex == -1) {
                result.append(value.substring(dollarIndex));
                break;
            }
            String varName = value.substring(dollarIndex + 2, endIndex);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                result.append(varValue);
            } else {
                result.append(value.substring(dollarIndex, endIndex + 1));
            }
            startIndex = endIndex + 1;
        } else {
            result.append('$');
            startIndex = dollarIndex + 1;
        }
    }
    return result.toString();
}

