            throw new IllegalArgumentException("Vertex " + vertex + " is not in the graph");
        }
    }

    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1.equals(vertex2)) {
                continue; // No need to check the same vertex
            }
            if (!graph.containsEdge(vertex1, vertex2)) {
                return false; // If any edge is missing, it's not a clique
            }
        }
    }

    return true; // All vertices are connected, it's a clique
}

