    if (lastSeparator > extensionPos) {
        return -1;
    }
    return extensionPos;
}

private static int indexOfLastSeparator(String filename) {
    int lastSeparator = -1;
    int pos = 0;
    while ((pos = filename.indexOf('/', pos)) != -1) {
        lastSeparator = pos;
        pos++;
    }
    pos = 0;
    while ((pos = filename.indexOf('\\', pos)) != -1) {
        lastSeparator = pos;
        pos++;
    }
    return lastSeparator;
}

